/* ==========================================================================
   Pixel Grocery Budget Tracker Styles
   Cohesive 4-Color Palette: #1a1a24 (Night), #e4e4e9 (Paper),
   #2d936c (Pixel Green), #d62246 (Pixel Red), #f39237 (Pixel Amber)
   ========================================================================== */

[hidden] {
  display: none !important;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Courier New', Courier, monospace, monospace;
  font-size: 16px;
  background-color: #242234;
  background-image: 
    linear-gradient(45deg, #1b1926 25%, transparent 25%), 
    linear-gradient(-45deg, #1b1926 25%, transparent 25%), 
    linear-gradient(45deg, transparent 75%, #1b1926 75%), 
    linear-gradient(-45deg, transparent 75%, #1b1926 75%);
  background-size: 24px 24px;
  background-position: 0 0, 0 12px, 12px -12px, -12px 0px;
  color: #1a1a24;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px 12px;
}

/* Accessibility utility */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Main Pixel Card */
.pixel-card {
  background-color: #f7f6f2;
  width: 100%;
  max-width: 520px;
  border: 4px solid #1a1a24;
  box-shadow: 8px 8px 0px #0e0d16;
  padding: 24px 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* Header */
.card-header {
  text-align: center;
  border-bottom: 4px dashed #1a1a24;
  padding-bottom: 16px;
}

.pixel-icon {
  font-size: 32px;
  margin-bottom: 4px;
}

.title {
  font-size: 26px;
  letter-spacing: 2px;
  font-weight: 900;
  text-transform: uppercase;
  color: #1a1a24;
}

.subtitle {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1px;
  color: #5b596d;
}

/* Panels */
.panel {
  background-color: #ffffff;
  border: 3px solid #1a1a24;
  box-shadow: 4px 4px 0px #1a1a24;
  padding: 16px;
}

.panel-title {
  font-size: 15px;
  font-weight: 900;
  letter-spacing: 1px;
  margin-bottom: 12px;
  color: #1a1a24;
}

/* Inputs & Labels */
.pixel-label {
  display: block;
  font-size: 13px;
  font-weight: 800;
  text-transform: uppercase;
  margin-bottom: 6px;
  color: #1a1a24;
}

.pixel-input {
  width: 100%;
  font-family: inherit;
  font-size: 16px;
  font-weight: bold;
  padding: 10px 12px;
  color: #1a1a24;
  background-color: #fff;
  border: 3px solid #1a1a24;
  box-shadow: 3px 3px 0px #9795a5;
  outline: none;
  transition: box-shadow 0.1s ease;
}

.pixel-input:focus {
  border-color: #1a1a24;
  box-shadow: 4px 4px 0px #2d936c;
  background-color: #fafaff;
}

.input-row {
  display: flex;
  flex-direction: column;
}

/* Form Layout */
.form-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 10px;
  margin-bottom: 14px;
}

@media (max-width: 440px) {
  .form-grid {
    grid-template-columns: 1fr;
  }
}

.form-group {
  display: flex;
  flex-direction: column;
}

/* Pixel Buttons */
.pixel-button {
  font-family: inherit;
  font-size: 16px;
  font-weight: 900;
  letter-spacing: 1px;
  text-transform: uppercase;
  cursor: pointer;
  border: 3px solid #1a1a24;
  box-shadow: 4px 4px 0px #1a1a24;
  padding: 12px 16px;
  outline: none;
  display: inline-block;
  text-align: center;
  user-select: none;
}

.pixel-button:hover {
  transform: translate(-1px, -1px);
  box-shadow: 5px 5px 0px #1a1a24;
}

.pixel-button:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0px #1a1a24;
}

.pixel-button:focus-visible {
  outline: 3px dashed #d62246;
  outline-offset: 3px;
}

.primary-btn {
  width: 100%;
  background-color: #2d936c;
  color: #ffffff;
}

.primary-btn:hover {
  background-color: #247b59;
}

.remove-btn {
  background-color: #d62246;
  color: #ffffff;
  font-size: 13px;
  padding: 6px 10px;
  border: 2px solid #1a1a24;
  box-shadow: 2px 2px 0px #1a1a24;
}

.remove-btn:hover {
  background-color: #b51939;
}

/* Grocery List Display */
.list-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
}

.badge {
  background: #1a1a24;
  color: #fff;
  font-size: 12px;
  font-weight: 800;
  padding: 3px 8px;
  letter-spacing: 1px;
}

.grocery-items {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 240px;
  overflow-y: auto;
  padding-right: 4px;
}

/* Custom Retro Scrollbar */
.grocery-items::-webkit-scrollbar {
  width: 8px;
}
.grocery-items::-webkit-scrollbar-track {
  background: #eae8e1;
  border: 2px solid #1a1a24;
}
.grocery-items::-webkit-scrollbar-thumb {
  background: #1a1a24;
}

.grocery-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #fdfdfd;
  border: 2px solid #1a1a24;
  box-shadow: 2px 2px 0px #b2b0bf;
  padding: 8px 10px;
  gap: 8px;
}

.item-details {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.item-name-text {
  font-weight: 800;
  font-size: 15px;
  color: #1a1a24;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.item-sub-text {
  font-size: 13px;
  color: #636173;
}

.item-right {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.item-subtotal {
  font-weight: 900;
  font-size: 15px;
  color: #1a1a24;
}

.empty-notice {
  text-align: center;
  font-size: 14px;
  font-style: italic;
  color: #727083;
  padding: 16px 0;
}

/* Summary & Alerts */
.summary-panel {
  background-color: #f0eee6;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.summary-row {
  display: flex;
  justify-content: space-between;
  font-weight: 900;
  font-size: 18px;
  border-bottom: 2px dotted #c5c3b9;
  padding-bottom: 4px;
}

.summary-val {
  font-family: inherit;
}

.summary-val.positive {
  color: #2d936c;
}

.summary-panel.over-budget {
  background-color: #ffd8df;
  border-color: #d62246;
}

.summary-panel.over-budget .summary-val {
  color: #d62246 !important;
}

.summary-panel.over-budget #total-spent {
  color: #d62246 !important;
  animation: pixel-pulse 1s infinite alternate;
}

.budget-banner {
  background-color: #d62246;
  color: #ffffff;
  font-weight: 900;
  text-align: center;
  padding: 8px 10px;
  font-size: 14px;
  letter-spacing: 1px;
  border: 2px solid #1a1a24;
  box-shadow: 2px 2px 0px #1a1a24;
  margin-top: 6px;
}

@keyframes pixel-pulse {
  from {
    transform: scale(1);
  }
  to {
    transform: scale(1.05);
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // State management
  let budget = 50.00;
  let items = [];

  // DOM element selections
  const budgetInput = document.getElementById('budget-input');
  const itemForm = document.getElementById('item-form');
  const itemNameInput = document.getElementById('item-name');
  const itemPriceInput = document.getElementById('item-price');
  const itemQtyInput = document.getElementById('item-qty');
  const groceryListEl = document.getElementById('grocery-list');
  const itemCountEl = document.getElementById('item-count');
  const emptyMessageEl = document.getElementById('empty-message');
  const totalSpentEl = document.getElementById('total-spent');
  const budgetLeftEl = document.getElementById('budget-left');
  const summaryPanel = document.getElementById('summary-panel');
  const budgetAlert = document.getElementById('budget-alert');

  // Currency formatting helper
  const formatCurrency = (val) => '$' + Math.abs(val).toFixed(2);

  // Update totals and over-budget visual states
  function updateTotals() {
    const totalSpent = items.reduce((acc, item) => acc + (item.price * item.quantity), 0);
    const remaining = budget - totalSpent;
    const isOver = totalSpent > budget;

    // Render texts
    totalSpentEl.textContent = formatCurrency(totalSpent);
    itemCountEl.textContent = `${items.length} ${items.length === 1 ? 'ITEM' : 'ITEMS'}`;

    if (remaining < 0) {
      budgetLeftEl.textContent = `-${formatCurrency(remaining)}`;
      budgetLeftEl.className = 'summary-val negative';
    } else {
      budgetLeftEl.textContent = formatCurrency(remaining);
      budgetLeftEl.className = 'summary-val positive';
    }

    // Over-budget alert styling
    if (isOver) {
      summaryPanel.classList.add('over-budget');
      totalSpentEl.style.color = '#d62246';
      budgetAlert.removeAttribute('hidden');
    } else {
      summaryPanel.classList.remove('over-budget');
      totalSpentEl.style.color = '';
      budgetAlert.setAttribute('hidden', '');
    }
  }

  // Render grocery items list
  function renderList() {
    groceryListEl.innerHTML = '';

    if (items.length === 0) {
      emptyMessageEl.removeAttribute('hidden');
    } else {
      emptyMessageEl.setAttribute('hidden', '');
    }

    items.forEach((item) => {
      const li = document.createElement('li');
      li.className = 'grocery-item';

      const detailsDiv = document.createElement('div');
      detailsDiv.className = 'item-details';

      const nameSpan = document.createElement('span');
      nameSpan.className = 'item-name-text';
      nameSpan.textContent = item.name;

      const subSpan = document.createElement('span');
      subSpan.className = 'item-sub-text';
      subSpan.textContent = `${item.quantity} × $${item.price.toFixed(2)}`;

      detailsDiv.appendChild(nameSpan);
      detailsDiv.appendChild(subSpan);

      const rightDiv = document.createElement('div');
      rightDiv.className = 'item-right';

      const subtotalSpan = document.createElement('span');
      subtotalSpan.className = 'item-subtotal';
      subtotalSpan.textContent = `$${(item.price * item.quantity).toFixed(2)}`;

      const removeBtn = document.createElement('button');
      removeBtn.type = 'button';
      removeBtn.className = 'pixel-button remove-btn';
      removeBtn.setAttribute('aria-label', `Remove ${item.name} from list`);
      removeBtn.textContent = 'DEL';

      removeBtn.addEventListener('click', () => {
        removeItem(item.id);
      });

      rightDiv.appendChild(subtotalSpan);
      rightDiv.appendChild(removeBtn);

      li.appendChild(detailsDiv);
      li.appendChild(rightDiv);
      groceryListEl.appendChild(li);
    });

    updateTotals();
  }

  // Add item handler
  function handleAddItem(e) {
    e.preventDefault();
    const name = itemNameInput.value.trim();
    const price = parseFloat(itemPriceInput.value);
    const qty = parseInt(itemQtyInput.value, 10);

    if (!name) {
      itemNameInput.focus();
      return;
    }
    if (isNaN(price) || price < 0) {
      itemPriceInput.focus();
      return;
    }
    if (isNaN(qty) || qty < 1) {
      itemQtyInput.focus();
      return;
    }

    const newItem = {
      id: Date.now().toString(),
      name,
      price,
      quantity: qty
    };

    items.push(newItem);
    renderList();

    // Reset entry inputs and refocus
    itemNameInput.value = '';
    itemPriceInput.value = '';
    itemQtyInput.value = '1';
    itemNameInput.focus();
  }

  // Remove item handler
  function removeItem(id) {
    items = items.filter(item => item.id !== id);
    renderList();
  }

  // Budget change handler
  function handleBudgetChange() {
    const newBudget = parseFloat(budgetInput.value);
    if (!isNaN(newBudget) && newBudget >= 0) {
      budget = newBudget;
    } else {
      budget = 0;
    }
    updateTotals();
  }

  // Event listeners
  itemForm.addEventListener('submit', handleAddItem);
  budgetInput.addEventListener('input', handleBudgetChange);

  // Initial render
  renderList();
});
